SELECT COUNT(*) FROM users as u, comments as c, postHistory as ph, votes as v WHERE c.UserId = u.Id AND v.UserId = u.Id AND ph.UserId = u.Id AND u.DownVotes<=0 AND u.UpVotes>=0 AND u.UpVotes<=72 AND ph.CreationDate>='2010-07-28 09:11:34'::timestamp AND ph.CreationDate<='2014-09-06 06:51:53'::timestamp;